* is called on incoming vtable calls
* (called by asm snippets)
*/
static void cpp_vtable_call( int nFunctionIndex, int nVtableOffset, void** gpregptr, void** fpregptr, void** ovrflw)
{
        sal_Int32     gpreg[8];
        memcpy( gpreg, gpregptr, 32);

#ifndef __NO_FPRS__
        double        fpreg[8];
        memcpy( fpreg, fpregptr, 64);
#endif

    volatile long nRegReturn[2];

        // fprintf(stderr,"in cpp_vtable_call nFunctionIndex is %x\n",nFunctionIndex);
        // fprintf(stderr,"in cpp_vtable_call nVtableOffset is %x\n",nVtableOffset);
        // fflush(stderr);

    typelib_TypeClass aType =
             cpp_mediate( nFunctionIndex, nVtableOffset, (void**)gpreg,
#ifndef __NO_FPRS__
                 (void**)fpreg,
#else
                 NULL,
#endif
                 ovrflw, (sal_Int64*)nRegReturn );

    switch( aType )
    {

                // move return value into register space
                // (will be loaded by machine code snippet)

                case typelib_TypeClass_BOOLEAN:
                case typelib_TypeClass_BYTE:
                  __asm__( "lbz 3,%0\n\t" : :
               "m"(nRegReturn[0]) );
                  break;

                case typelib_TypeClass_CHAR:
                case typelib_TypeClass_SHORT:
                case typelib_TypeClass_UNSIGNED_SHORT:
                  __asm__( "lhz 3,%0\n\t" : :
               "m"(nRegReturn[0]) );
                  break;

        case typelib_TypeClass_FLOAT:
#ifndef __NO_FPRS__
                  __asm__( "lfs 1,%0\n\t" : :
                           "m" (*((float*)nRegReturn)) );
 #else
                  __asm__( "lwz 3,%0\n\t" : :
                           "m"(nRegReturn[0]) );
#endif
          break;

        case typelib_TypeClass_DOUBLE:
#ifndef __NO_FPRS__
          __asm__( "lfd 1,%0\n\t" : :
                           "m" (*((double*)nRegReturn)) );
#else
          __asm__( "lwz 3,%0\n\t" : :
                           "m"(nRegReturn[0]) );
          __asm__( "lwz 4,%0\n\t" : :
                           "m"(nRegReturn[1]) );
#endif
          break;

        case typelib_TypeClass_HYPER:
        case typelib_TypeClass_UNSIGNED_HYPER:
          __asm__( "lwz 4,%0\n\t" : :
                           "m"(nRegReturn[1]) );  // fall through

        default:
          __asm__( "lwz 3,%0\n\t" : :
                           "m"(nRegReturn[0]) );
          break;
    }
}

